TLM.f("Sancti/06-04",{"officium":"S. Francisci Caracciolo Confessoris","rule":["vide C4;","Gloria"],"fallback":"Commune/C5","from":{"Tractus":"Commune/C5","Evangelium":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 68:10"},{"k":"text","la":"Factum est cor meum tamquam cera liquéscens in médio ventris mei: quóniam zelus domus tuæ comédit me. (Allelúja, allelúja)"},{"k":"ref","la":"Ps 72:1"},{"k":"text","la":"Quam bonus Israël Deus: his, qui recto sunt corde!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Factum est cor meum tamquam cera liquéscens in médio ventris mei: quóniam zelus domus tuæ comédit me. (Allelúja, allelúja)"}],"Oratio":[{"k":"text","la":"Deus, qui beátum Francíscum, novi órdinis institutórem, orándi stúdio et pœniténtiæ amóre decorásti: da fámulis tuis in ejus imitatióne ita profícere; ut, semper orántes et corpus in servitútem redigéntes, ad cœléstem glóriam perveníre mereántur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 4:7-14"},{"k":"text","la":"Justus, si morte præoccupátus fúerit, in refrigério erit. Senéctus enim venerábilis est non diutúrna, neque annórum número computáta: cani autem sunt sensus hóminis, et ætas senectútis vita immaculáta. Placens Deo Jactus est diléctus, et vivens inter peccatóres translátus est. Raptus est, ne malítia mutáret intelléctum ejus, aut ne fíctio decíperet ánimam illíus. Fascinátio enim nugacitátis obscúrat bona, et inconstántia concupiscéntiæ transvértit sensum sine malítia. Consummátus in brevi explévit témpora multa, plácita enim erat Deo ánima illíus: propter hoc properávit edúcere illum de médio iniquitátum."}],"Graduale":[{"k":"ref","la":"Ps 41:2"},{"k":"text","la":"Quemádmodum desíderat cervus ad fontes aquárum: ita desíderat ánima mea ad te, Deus."},{"k":"ref","la":"Ps 41:3"},{"k":"text","la":"Sitívit ánima mea ad Deum fortem vivum."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 72:26"},{"k":"text","la":"Defécit caro mea et cor meum: Deus cordis mei, et pars mea Deus in ætérnum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 64:5"},{"k":"text","la":"Beátus, quem elegísti et assumpsísti: inhabitábit in átriis tuis. Allelúja."},{"k":"ref","la":"Ps 111:9"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:35-40"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Da nobis, clementíssime Jesu: ut præclára beáti Francísci mérita recoléntes, eódem nos, ac ille, caritátis igne succénsi, digne in circúitu sacræ hujus mensæ tuæ esse valeámus:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"ref","la":"Ps 30:20"},{"k":"text","la":"Quam magna multitúdo dulcédinis tuæ, Dómine, quam abscondísti timéntibus te! ~(Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sacrosáncta sacrifícii, quǽsumus, Dómine, quod hódie in sollemnitáte beáti Francísci tuæ obtúlimus majestáti, grata semper in méntibus nostris memória persevéret et fructus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ccfba8e3ab1bef95":{"t":"Ps 21, 15, Ps 68, 10, Ps 72, 1\n(Ps 21, 15, Ps 68, 10) Srce mi je postalo kao vosak, rastopilo se u meni, jer me izjeda revnost za domom tvojim. (Ps 72, 1) Kako je dobar Bog za Izraela, za sve one koji su pravedna srca!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 21, 15, Ps 68, 10) Srce mi je postalo kao vosak, rastopilo se u meni, jer me izjeda revnost za domom tvojim."},"3e26efe0b82c5449":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Franju, osnivača novoga reda. ukrasio revnošću u molitvi i ljubavlju prema pokori, daj svojim slugama tako napredovati u njegovu nasljedovanju da se uvijek mole i duhu podvrgavaju tijelo pa da zavrijede doći u nebesku slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7c3d366b1d42f68b":{"t":"Mudr 4, 7-14\nČitanje knjige Mudrosti. Pravednik će uživati mir, i ako ga zateče rana smrti. Časna starost nije u dugom životu ni u broju godina, nego bijela kosa je čovječja mudrost, a staračko doba neokaljan život. Bog ga je zavolio, jer mu je ugodio, prenio ga, jer ga je udaljio od grješnika. Bio je uzet, da ne bi zloba promijenila njegova razuma, ili da ne bi varka zamamila njegove duše, jer čar ispraznosti zasjenjuje dobro, i nestalnost požude prevrće bezazlen duh. Dozreo je u kratko vrijeme i ispunio dugi život. Bogu se svidjela njegova duša, i zato se požurio, da ga izvede iz opačina."},"951e988b3d1e5b58":{"t":"Ps 41, 2, Ps 41, 3\n(Ps 41, 2) Kao što čezne jelen za izvorima vođe, tako čezne duša moja za tobom, Bože. (Ps 41, 3) Žeđa duša moja Boga jakoga i živoga.\n\nPs 72, 26\n<i>Aleluja</i>, <i>aleluja</i>.\nSve da nestane tijela moga i srca moga, ti ćeš ipak ostati Bog srca moga i moja vječna baština. <i>Aleluja</i>."},"52bdf7255321563a":{"t":"Lk 12, 35-40\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Isus reče svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama, a vi budite slični slugama koji očekuju svojega gospodara, kada se vraća sa svadbe, da mu smjesta otvore vrata, čim dođe i pokuca. Blago onim slugama koje gospodar kada dođe nađe budne! Uvjeravam vas, da će se sam pripasati, narediti im da sjednu za stol i poslužiti ih. Blago tim slugama, ako ih nađe tako došao on bilo o drugoj, ili o trećoj straži. Pazite: Kada bi domaćin znao u koji čas dolazi tat, ne bi dopustio potkopati svoje kuće. Zato budite pripravni i vi, jer će Čovječji Sin doći u čas, kada vi i ne slutite."},"26bc9b7e0a4c66c8":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar."},"cabebe7e8863ccf0":{"t":"Daj nam, preblagi Isuse, da slaveći divne zasluge blaženog Franje raspaljeni kao i on istim ognjem ljubavi, uzmognemo dostojno sudjelovati kod ovoga tvog svetog stola:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"a0841528526d07c2":{"t":"Ps 30, 20\nKako je veliko obilje miline tvoje, Gospodine, što je čuvaš za one koji te se boje!"},"6241cf6b85345739":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da u našim dušama uvijek traje draga uspomena i plod presvete žrtve, koju smo danas o svetkovini blaženog Franje prikazali tvome veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0409665367a82cb9":{"t":"Ps 21, 15, Ps 68, 10, Ps 72, 1\n(Ps 21, 15, Ps 68, 10) Srce mi je postalo kao vosak, rastopilo se u meni, jer me izjeda revnost za domom tvojim. (Ps 72, 1) Kako je dobar Bog za Izraela, za sve one koji su pravedna srca!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 21, 15, Ps 68, 10) Srce mi je postalo kao vosak, rastopilo se u meni, jer me izjeda revnost za domom tvojim.","v":"∅ → aleluia aleluia; ∅ → aleluia aleluia"},"1961f1522dfee2e6":{"t":"Ps 64, 5\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago onome koga si ti odabrao i primio da prebiva u dvorima tvojim. <i>Aleluja</i>.\n\nPs 111, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nObilno je dijelio i davao siromasima, darežljivost njegova ostaje dovijeka. <i>Aleluja</i>.","v":"sastavljeno iz dva dijela"},"5df0301ba9f14238":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar. <i>Aleluja</i>."},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"d384b35d7205818e":{"t":"Ps 30, 20\nKako je veliko obilje miline tvoje, Gospodine, što je čuvaš za one koji te se boje!","v":"∅ → aleluia"}}});
